import re

def entities(doc, scope) -> list:
    child_nodes = scope_nodes(doc, scope)
    result = []
    for node in child_nodes:
        if node["kind"] == "list" and ": Objects" in node["title"]:
            for line in node.get("lines", []):
                match = re.match(r'Object (\d+): (.+)', line)
                if match:
                    result.append({"id": match.group(1), "description": match.group(2)})
    return result

def recorded_end(doc, scope) -> float:
    child_nodes = scope_nodes(doc, scope)
    max_frame = 0.0
    for node in child_nodes:
        if node["kind"] == "table" and ": Motion log" in node["title"]:
            for row_idx, row_data in table_rows(node):
                frame = float(row_data["frame"])
                if frame > max_frame:
                    max_frame = frame
        elif node["kind"] == "list" and ": Events" in node["title"]:
            for line in node.get("lines", []):
                match = re.match(r'Frame (\d+):', line)
                if match:
                    frame = float(match.group(1))
                    if frame > max_frame:
                        max_frame = frame
    return max_frame

def inputs(doc, scope) -> list:
    child_nodes = scope_nodes(doc, scope)
    events_node = None
    for node in child_nodes:
        if node["kind"] == "list" and ": Events" in node["title"]:
            events_node = node
            break
    result = []
    if not events_node:
        return result
    lines = events_node.get("lines", [])
    for i, line in enumerate(lines):
        match = re.match(r'Frame (\d+): Object (\d+) \((.+)\) is in view when the video begins\.', line)
        if match:
            result.append({
                "id": f"enter_{match.group(2)}_frame{match.group(1)}",
                "time": float(match.group(1)),
                "kind": "enter",
                "entities": [match.group(2)],
                "fields": {"description": match.group(3)},
                "src": [[events_node["node_id"], i]]
            })
            continue
        match = re.match(r'Frame (\d+): Object (\d+) \((.+)\) enters the scene\.', line)
        if match:
            result.append({
                "id": f"enter_{match.group(2)}_frame{match.group(1)}",
                "time": float(match.group(1)),
                "kind": "enter",
                "entities": [match.group(2)],
                "fields": {"description": match.group(3)},
                "src": [[events_node["node_id"], i]]
            })
    return result

def outcomes(doc, scope) -> list:
    child_nodes = scope_nodes(doc, scope)
    events_node = None
    for node in child_nodes:
        if node["kind"] == "list" and ": Events" in node["title"]:
            events_node = node
            break
    result = []
    if not events_node:
        return result
    lines = events_node.get("lines", [])
    for i, line in enumerate(lines):
        collision_match = re.match(r'Frame (\d+): Object (\d+) \(.+?\) collides with Object (\d+) \(.+?\)', line)
        if collision_match:
            result.append({
                "time": float(collision_match.group(1)),
                "kind": "collision",
                "entities": [collision_match.group(2), collision_match.group(3)],
                "value": None,
                "src": [[events_node["node_id"], i]]
            })
            continue
        exit_match = re.match(r'Frame (\d+): Object (\d+) .+ exits the scene', line)
        if exit_match:
            result.append({
                "time": float(exit_match.group(1)),
                "kind": "exit",
                "entities": [exit_match.group(2)],
                "value": None,
                "src": [[events_node["node_id"], i]]
            })
    return result

