import math

def simulate(doc, scope, inputs, params, start=None, horizon=None):
    # Locate motion log for the scope
    child_nodes = scope_nodes(doc, scope)
    motion_node = None
    for n in child_nodes:
        if n["kind"] == "table" and ": Motion log" in n["title"]:
            motion_node = n
            break

    motion_data = []
    if motion_node:
        for row in motion_node["table"]["rows"]:
            motion_data.append({
                "f": int(row[0]),
                "id": row[1].split(" ")[0],
                "x": float(row[2]), "y": float(row[3]),
                "vx": float(row[4]), "vy": float(row[5]),
                "s": float(row[6])
            })

    if start is None:
        start = 0.0
    if horizon is None:
        horizon = 127.0

    state = {}
    # Scale factor: velocities in log are m/s, frame duration ~ 5/128 s
    scale = 5.0 / 128.0 

    # Initialise state at `start` from latest records <= start
    latest = {}
    for m in motion_data:
        if m["f"] <= start:
            if m["id"] not in latest or m["f"] > latest[m["id"]]["f"]:
                latest[m["id"]] = m

    for inp in inputs:
        obj_id = inp["entities"][0]
        t_in = inp["time"]
        if t_in <= start:
            if obj_id in latest:
                rec = latest[obj_id]
                state[obj_id] = {
                    "x": rec["x"], "y": rec["y"],
                    "vx": rec["vx"] * scale, "vy": rec["vy"] * scale,
                    "active": True
                }
            else:
                # Fallback if not in motion log (should rarely happen if inputs align)
                state[obj_id] = {"x": 0.0, "y": 0.0, "vx": 0.0, "vy": 0.0, "active": True}

    # Queue future entries
    future_entries = {}
    for inp in inputs:
        if inp["time"] > start:
            future_entries[int(inp["time"])] = inp["entities"][0]

    outcomes = []
    t = start
    dt = 1.0
    COLL_THRESH = 0.5      # ~distance where objects touch
    FRICTION = 0.993       # ~velocity decay per frame estimated from data
    RESTITUTION = 0.5      # moderate elasticity
    BOUND = 4.0            # scene boundary threshold

    while t <= horizon:
        # Handle new entries
        if int(t) in future_entries:
            oid = future_entries[int(t)]
            state[oid] = {"x": 0.0, "y": 0.0, "vx": 0.0, "vy": 0.0, "active": True}

        # Step positions & apply friction
        for oid, s in state.items():
            s["x"] += s["vx"]
            s["y"] += s["vy"]
            s["vx"] *= FRICTION
            s["vy"] *= FRICTION

        # Collision detection & response
        oids = list(state.keys())
        for i in range(len(oids)):
            for j in range(i+1, len(oids)):
                s1, s2 = state[oids[i]], state[oids[j]]
                dx, dy = s1["x"] - s2["x"], s1["y"] - s2["y"]
                dist = math.hypot(dx, dy)
                if 0 < dist < COLL_THRESH:
                    outcomes.append({
                        "time": t,
                        "kind": "collision",
                        "entities": [oids[i], oids[j]],
                        "value": None,
                        "src": []
                    })
                    # Impulse resolution along normal
                    nx, ny = dx / dist, dy / dist
                    dvx, dvy = s1["vx"] - s2["vx"], s1["vy"] - s2["vy"]
                    dvn = dvx * nx + dvy * ny
                    if dvn < 0:  # approaching
                        imp = -(1 + RESTITUTION) * dvn / 2.0
                        s1["vx"] += imp * nx
                        s1["vy"] += imp * ny
                        s2["vx"] -= imp * nx
                        s2["vy"] -= imp * ny

        # Exit detection
        for oid in list(state.keys()):
            s = state[oid]
            if abs(s["x"]) > BOUND or abs(s["y"]) > BOUND:
                outcomes.append({
                    "time": t,
                    "kind": "exit",
                    "entities": [oid],
                    "value": None,
                    "src": []
                })
                del state[oid]

        t += dt

    return outcomes

