# ---- step 2: forward model ----
import math
from collections import defaultdict

def simulate(doc, scope, inputs, params, start=None, horizon=None):
    stationary_threshold = params.get("stationary_threshold", 0.1)

    # Get object info
    all_entities = entities(doc, scope)
    obj_material = {}
    for e in all_entities:
        obj_material[e["id"]] = "metal" if "metal" in e["description"] else "rubber"

    # Get motion data from the scope
    child_nodes = scope_nodes(doc, scope)
    motion_rows = []
    for n in child_nodes:
        if n["kind"] == "table" and ": Motion log" in n["title"]:
            motion_rows = list(table_rows(n))
            break

    # Parse motion data by object
    all_motion = defaultdict(list)
    for ridx, r in motion_rows:
        obj_id = r["object"].split()[0]
        all_motion[obj_id].append({
            "frame": int(r["frame"]),
            "x": float(r["x"]),
            "y": float(r["y"]),
            "vx": float(r["vx"]),
            "vy": float(r["vy"])
        })

    # Build entity states from inputs only
    entity_state = {}
    for inp in inputs:
        if inp["kind"] == "enter":
            obj_id = inp["entities"][0]
            entity_state[obj_id] = {
                "x": 0.0, "y": 0.0, "vx": 0.0, "vy": 0.0,
                "enter_time": inp["time"],
                "exited": False,
                "material": obj_material.get(obj_id, "rubber"),
                "initialized": False
            }

    if start is None:
        start = 0.0
    if horizon is None:
        horizon = recorded_end(doc, scope)

    def init_entity_at(obj_id, time):
        """Initialize entity state from motion log at or before given time."""
        s = entity_state.get(obj_id)
        if not s or s["initialized"]:
            return
        if obj_id in all_motion:
            records = sorted(all_motion[obj_id], key=lambda x: x["frame"])
            best = None
            for rec in records:
                if rec["frame"] <= time:
                    best = rec
            if best:
                dt = time - best["frame"]
                s["x"] = best["x"] + best["vx"] * dt
                s["y"] = best["y"] + best["vy"] * dt
                s["vx"] = best["vx"]
                s["vy"] = best["vy"]
        s["initialized"] = True

    # Initialize entities present at start
    for obj_id, s in entity_state.items():
        if s["enter_time"] <= start:
            init_entity_at(obj_id, start)

    # Physics parameters estimated from recorded data
    friction_rate = {"rubber": 0.02, "metal": 0.005}
    collision_dist = 0.7
    exit_bound = 4.0
    restitution_map = {"rubber": 0.8, "metal": 1.0}

    outcomes = []
    collided_pairs = set()

    t = int(math.floor(start))

    while t < horizon:
        # Initialize entities that enter at or before this frame
        for obj_id in entity_state:
            s = entity_state[obj_id]
            if not s["initialized"] and s["enter_time"] <= t:
                init_entity_at(obj_id, t)

        # Update active entities: apply friction and move
        for obj_id, s in entity_state.items():
            if not s["initialized"] or s["exited"] or s["enter_time"] > t:
                continue
            fric = friction_rate[s["material"]]
            vx, vy = s["vx"], s["vy"]
            speed = math.sqrt(vx * vx + vy * vy)

            if speed > stationary_threshold:
                # Apply constant friction deceleration per component
                if abs(vx) > 0.001:
                    s["vx"] = vx - fric * (1.0 if vx > 0 else -1.0)
                    if s["vx"] * vx < 0:
                        s["vx"] = 0.0
                else:
                    s["vx"] = 0.0
                if abs(vy) > 0.001:
                    s["vy"] = vy - fric * (1.0 if vy > 0 else -1.0)
                    if s["vy"] * vy < 0:
                        s["vy"] = 0.0
                else:
                    s["vy"] = 0.0
            else:
                s["vx"] = 0.0
                s["vy"] = 0.0

            # Update position
            s["x"] += s["vx"]
            s["y"] += s["vy"]

        t += 1

        # Check collisions at time t
        active = [oid for oid, s in entity_state.items()
                  if s["initialized"] and not s["exited"] and s["enter_time"] <= t]

        for i in range(len(active)):
            for j in range(i + 1, len(active)):
                id1, id2 = active[i], active[j]
                s1, s2 = entity_state[id1], entity_state[id2]

                dx = s2["x"] - s1["x"]
                dy = s2["y"] - s1["y"]
                dist = math.sqrt(dx * dx + dy * dy)

                if dist < collision_dist and dist > 0.001:
                    pair = tuple(sorted([id1, id2]))
                    if pair not in collided_pairs:
                        collided_pairs.add(pair)

                        outcomes.append({
                            "time": float(t),
                            "kind": "collision",
                            "entities": [id1, id2],
                            "value": None,
                            "src": []
                        })

                        # Elastic collision response
                        nx, ny = dx / dist, dy / dist
                        dvx = s1["vx"] - s2["vx"]
                        dvy = s1["vy"] - s2["vy"]
                        dv_dot_n = dvx * nx + dvy * ny

                        if dv_dot_n > 0:
                            rest = restitution_map[s1["material"]] * restitution_map[s2["material"]]
                            impulse = (1.0 + rest) * dv_dot_n / 2.0
                            s1["vx"] -= impulse * nx
                            s1["vy"] -= impulse * ny
                            s2["vx"] += impulse * nx
                            s2["vy"] += impulse * ny

                        # Separate overlapping objects
                        overlap = collision_dist - dist
                        if overlap > 0:
                            s1["x"] -= overlap * nx * 0.5
                            s1["y"] -= overlap * ny * 0.5
                            s2["x"] += overlap * nx * 0.5
                            s2["y"] += overlap * ny * 0.5

        # Check exits at time t
        for obj_id, s in entity_state.items():
            if s["initialized"] and not s["exited"]:
                if abs(s["x"]) > exit_bound or abs(s["y"]) > exit_bound:
                    s["exited"] = True
                    outcomes.append({
                        "time": float(t),
                        "kind": "exit",
                        "entities": [obj_id],
                        "value": None,
                        "src": []
                    })

    # Only return outcomes after start
    outcomes = [o for o in outcomes if o["time"] > start]

    return outcomes

