import math
from collections import defaultdict

def simulate(doc, scope, inputs, params, start=None, horizon=None):
    stationary_threshold = params.get("stationary_threshold", 0.1)

    # Get object info from entities
    all_entities = entities(doc, scope)
    obj_material = {}
    for e in all_entities:
        obj_material[e["id"]] = "metal" if "metal" in e["description"] else "rubber"

    # Read motion log data
    child_nodes = scope_nodes(doc, scope)
    motion_rows = []
    for n in child_nodes:
        if n["kind"] == "table" and ": Motion log" in n["title"]:
            motion_rows = list(table_rows(n))
            break

    # Parse motion data by object
    all_motion = defaultdict(list)
    for ridx, r in motion_rows:
        parts = r["object"].split()
        obj_id = parts[0]
        all_motion[obj_id].append({
            "frame": int(r["frame"]),
            "x": float(r["x"]),
            "y": float(r["y"]),
            "vx": float(r["vx"]),
            "vy": float(r["vy"]),
            "speed": float(r["speed"])
        })

    # Build entity states from inputs only
    active_objects = set()
    for inp in inputs:
        if inp["kind"] == "enter":
            active_objects.add(inp["entities"][0])

    if start is None:
        start = 0.0
    if horizon is None:
        horizon = recorded_end(doc, scope)

    def get_state_at_frame(obj_id, frame):
        """Get the latest recorded state at or before a given frame."""
        records = sorted(all_motion.get(obj_id, []), key=lambda x: x["frame"])
        best = None
        for rec in records:
            if rec["frame"] <= frame:
                best = rec
        return best

    def extrapolate_state(rec, target_time):
        """Extrapolate a state record to a target time using its velocity."""
        if rec is None:
            return None
        dt = target_time - rec["frame"]
        return {
            "x": rec["x"] + rec["vx"] * dt,
            "y": rec["y"] + rec["vy"] * dt,
            "vx": rec["vx"],
            "vy": rec["vy"]
        }

    # Initialize entity states
    entity_state = {}
    for obj_id in active_objects:
        rec = get_state_at_frame(obj_id, start)
        state = extrapolate_state(rec, start)
        if state:
            entity_state[obj_id] = state
        else:
            # Use enter time to find initial state
            for inp in inputs:
                if inp["kind"] == "enter" and inp["entities"][0] == obj_id:
                    enter_frame = inp["time"]
                    rec = get_state_at_frame(obj_id, enter_frame)
                    if rec:
                        entity_state[obj_id] = extrapolate_state(rec, start)
                    else:
                        entity_state[obj_id] = {"x": 0.0, "y": 0.0, "vx": 0.0, "vy": 0.0}
                    break

    # Physics parameters
    friction_rate = {"rubber": 0.02, "metal": 0.005}
    collision_dist = 0.75
    exit_bound = 4.0
    restitution_map = {"rubber": 0.8, "metal": 1.0}

    outcomes = []
    collided_pairs = set()

    # Start simulation at integer frame just after start
    t = int(math.ceil(start))
    if t < int(math.floor(start)) + 1:
        t = int(math.floor(start)) + 1

    while t <= horizon:
        # Update entity states: apply friction and move
        for obj_id in list(entity_state.keys()):
            s = entity_state[obj_id]
            mat = obj_material.get(obj_id, "rubber")
            fric = friction_rate[mat]
            vx, vy = s["vx"], s["vy"]
            speed = math.sqrt(vx * vx + vy * vy)

            if speed > stationary_threshold:
                # Apply friction proportional to direction
                if vx != 0:
                    s["vx"] = vx - fric * (1.0 if vx > 0 else -1.0)
                    if s["vx"] * vx < 0:
                        s["vx"] = 0.0
                else:
                    s["vx"] = 0.0
                if vy != 0:
                    s["vy"] = vy - fric * (1.0 if vy > 0 else -1.0)
                    if s["vy"] * vy < 0:
                        s["vy"] = 0.0
                else:
                    s["vy"] = 0.0
            else:
                s["vx"] = 0.0
                s["vy"] = 0.0

            # Update position
            s["x"] += s["vx"]
            s["y"] += s["vy"]

        # Check collisions at time t
        active = list(entity_state.keys())

        for i in range(len(active)):
            for j in range(i + 1, len(active)):
                id1, id2 = active[i], active[j]
                s1, s2 = entity_state[id1], entity_state[id2]

                dx = s2["x"] - s1["x"]
                dy = s2["y"] - s1["y"]
                dist = math.sqrt(dx * dx + dy * dy)

                if dist < collision_dist and dist > 0.001:
                    pair = tuple(sorted([id1, id2]))
                    if pair not in collided_pairs:
                        collided_pairs.add(pair)

                        outcomes.append({
                            "time": float(t),
                            "kind": "collision",
                            "entities": [id1, id2],
                            "value": None,
                            "src": []
                        })

                        # Elastic collision response
                        nx, ny = dx / dist, dy / dist
                        dvx = s1["vx"] - s2["vx"]
                        dvy = s1["vy"] - s2["vy"]
                        dv_dot_n = dvx * nx + dvy * ny

                        if dv_dot_n > 0:
                            rest = restitution_map[s1["material"] if "material" in s1 else obj_material.get(id1, "rubber")] * restitution_map[s2["material"] if "material" in s2 else obj_material.get(id2, "rubber")]
                            impulse = (1.0 + rest) * dv_dot_n / 2.0
                            s1["vx"] -= impulse * nx
                            s1["vy"] -= impulse * ny
                            s2["vx"] += impulse * nx
                            s2["vy"] += impulse * ny

                        # Separate overlapping objects
                        overlap = collision_dist - dist
                        if overlap > 0:
                            s1["x"] -= overlap * nx * 0.5
                            s1["y"] -= overlap * ny * 0.5
                            s2["x"] += overlap * nx * 0.5
                            s2["y"] += overlap * ny * 0.5

        # Check exits at time t
        for obj_id in list(entity_state.keys()):
            s = entity_state[obj_id]
            if abs(s["x"]) > exit_bound or abs(s["y"]) > exit_bound:
                outcomes.append({
                    "time": float(t),
                    "kind": "exit",
                    "entities": [obj_id],
                    "value": None,
                    "src": []
                })
                del entity_state[obj_id]

        t += 1

    # Only return outcomes after start
    outcomes = [o for o in outcomes if o["time"] > start]

    return outcomes

