import math

def simulate(doc, scope, inputs, params, start=None, horizon=None):
    # Read motion log from the scope
    child_nodes = scope_nodes(doc, scope)
    motion_rows = []
    for n in child_nodes:
        if n["kind"] == "table" and ": Motion log" in n["title"]:
            motion_rows = list(table_rows(n))
            break

    # Parse motion data into a frame-indexed dict
    motion_data = {}
    for _, r in motion_rows:
        f = int(r["frame"])
        oid = r["object"].split()[0]
        if f not in motion_data:
            motion_data[f] = {}
        motion_data[f][oid] = {
            "x": float(r["x"]), "y": float(r["y"]),
            "vx": float(r["vx"]), "vy": float(r["vy"]),
            "speed": float(r["speed"])
        }

    if start is None:
        start = 0.0
    if horizon is None:
        horizon = recorded_end(doc, scope)

    # Only consider entities that have inputs
    active_ids = set()
    for inp in inputs:
        if inp["kind"] == "enter":
            active_ids.add(inp["entities"][0])

    state = {}
    start_frame = int(math.floor(start)) + 1

    # Initialize state at start_frame from latest records at or before start
    for oid in active_ids:
        best_f = -1
        best_rec = None
        for f in motion_data:
            if f <= start and oid in motion_data[f]:
                if f > best_f:
                    best_f = f
                    best_rec = motion_data[f][oid]

        if best_rec:
            dt = start - best_f
            state[oid] = {
                "x": best_rec["x"] + best_rec["vx"] * dt,
                "y": best_rec["y"] + best_rec["vy"] * dt,
                "vx": best_rec["vx"],
                "vy": best_rec["vy"],
                "exited": False
            }
        else:
            # Fallback if no prior record
            state[oid] = {"x": 0.0, "y": 0.0, "vx": 0.0, "vy": 0.0, "exited": False}

    outcomes = []
    recorded_collisions = set()
    # Estimated thresholds from CLEVRER physics: radius ~0.5, collision when centers < 1.0
    # Exit when coordinate magnitude exceeds scene boundary (~3.8)
    coll_dist = 1.05
    exit_bound = 3.8

    for t in range(start_frame, int(horizon) + 1):
        # Update state for each active object
        for oid in state:
            s = state[oid]
            if s["exited"]:
                continue
            # Snap to recorded data if available for this frame
            if t in motion_data and oid in motion_data[t]:
                rec = motion_data[t][oid]
                s["x"], s["y"], s["vx"], s["vy"] = rec["x"], rec["y"], rec["vx"], rec["vy"]
            else:
                # Propagate forward with constant velocity
                s["x"] += s["vx"]
                s["y"] += s["vy"]
                # Stop if speed drops below stationary threshold
                spd = math.hypot(s["vx"], s["vy"])
                if spd < 0.1:
                    s["vx"] = s["vy"] = 0.0

        # Check collisions at this frame
        oids = list(state.keys())
        for i in range(len(oids)):
            for j in range(i + 1, len(oids)):
                oid1, oid2 = oids[i], oids[j]
                s1, s2 = state[oid1], state[oid2]
                if s1["exited"] or s2["exited"]:
                    continue
                dist = math.hypot(s2["x"] - s1["x"], s2["y"] - s1["y"])
                if dist < coll_dist:
                    pair = tuple(sorted([oid1, oid2]))
                    if pair not in recorded_collisions:
                        recorded_collisions.add(pair)
                        outcomes.append({
                            "time": float(t),
                            "kind": "collision",
                            "entities": [oid1, oid2],
                            "value": None,
                            "src": []
                        })

        # Check exits at this frame
        for oid in state:
            s = state[oid]
            if s["exited"]:
                continue
            if abs(s["x"]) > exit_bound or abs(s["y"]) > exit_bound:
                s["exited"] = True
                outcomes.append({
                    "time": float(t),
                    "kind": "exit",
                    "entities": [oid],
                    "value": None,
                    "src": []
                })

    return outcomes

