                        s["vx"] = 0.0

                    if abs(vy) > 0.0001:
                        new_vy = vy - fric * (1.0 if vy > 0 else -1.0)
                        if new_vy * vy < 0:
                            new_vy = 0.0
                        s["vy"] = new_vy
                    else:
                        s["vy"] = 0.0
                else:
                    s["vx"] = 0.0
                    s["vy"] = 0.0

                # Move
                s["x"] += s["vx"]
                s["y"] += s["vy"]

        # Check collisions - objects that are not exited
        oids = [oid for oid in state if not state[oid]["exited"]]
        for i in range(len(oids)):
            for j in range(i + 1, len(oids)):
                oid1, oid2 = oids[i], oids[j]
                s1, s2 = state[oid1], state[oid2]

                dist = math.hypot(s2["x"] - s1["x"], s2["y"] - s1["y"])

                if dist < collision_dist:
                    pair = tuple(sorted([oid1, oid2]))
                    if pair not in recorded_collisions:
                        recorded_collisions.add(pair)
                        outcomes.append({
                            "time": float(t),
                            "kind": "collision",
                            "entities": [oid1, oid2],
                            "value": None,
                            "src": []
                        })

        # Check exits - only if position exceeds boundary significantly
        for oid in list(state.keys()):
            s = state[oid]
            if s["exited"]:
                continue
            if abs(s["x"]) > exit_bound and abs(s["y"]) > exit_bound:
                s["exited"] = True
                outcomes.append({
                    "time": float(t),
                    "kind": "exit",
                    "entities": [oid],
                    "value": None,
                    "src": []
                })

        t += 1

    # Filter outcomes after start
    return [o for o in outcomes if o["time"] > start]

