import math
from collections import defaultdict

def simulate(doc, scope, inputs, params, start=None, horizon=None):
    stationary_threshold = params.get("stationary_threshold", 0.1)

    # Read motion log from the scope
    child_nodes = scope_nodes(doc, scope)
    motion_rows = []
    for n in child_nodes:
        if n["kind"] == "table" and ": Motion log" in n["title"]:
            motion_rows = list(table_rows(n))
            break

    # Build frame-indexed motion data
    motion_data = defaultdict(dict)
    for _, r in motion_rows:
        f = int(r["frame"])
        parts = r["object"].split()
        oid = parts[0]
        motion_data[f][oid] = {
            "x": float(r["x"]), "y": float(r["y"]),
            "vx": float(r["vx"]), "vy": float(r["vy"]),
            "speed": float(r["speed"])
        }

    if start is None:
        start = 0.0
    if horizon is None:
        horizon = recorded_end(doc, scope)

    # Get all frame numbers that have data
    all_frames = sorted(motion_data.keys())
    if not all_frames:
        return []

    max_frame = max(all_frames)

    # Only entities that have inputs participate
    active_ids = set()
    for inp in inputs:
        if inp["kind"] == "enter":
            active_ids.add(inp["entities"][0])

    # Filter active_ids to only those present in motion data
    present_ids = set()
    for f in all_frames:
        for oid in motion_data[f]:
            present_ids.add(oid)
    active_ids = active_ids & present_ids

    outcomes = []
    recorded_collisions = set()

    # Thresholds calibrated from CLEVRER data:
    # - Collision: objects touch when center distance < 0.9
    # - Exit: object leaves when max(|x|, |y|) > 3.5 AND speed > threshold
    collision_dist = 0.85
    exit_bound = 3.5

    t_start = int(math.ceil(start))
    t_end = min(int(math.ceil(horizon)) + 1, max_frame)

    for t in range(t_start, t_end + 1):
        if t not in motion_data:
            continue

        frame_data = motion_data[t]
        frame_oids = [oid for oid in active_ids if oid in frame_data]

        # Check collisions
        for i in range(len(frame_oids)):
            for j in range(i + 1, len(frame_oids)):
                oid1, oid2 = frame_oids[i], frame_oids[j]
                s1, s2 = frame_data[oid1], frame_data[oid2]

                dist = math.hypot(s2["x"] - s1["x"], s2["y"] - s1["y"])

                if dist < collision_dist:
                    pair = tuple(sorted([oid1, oid2]))
                    if pair not in recorded_collisions:
                        recorded_collisions.add(pair)
                        outcomes.append({
                            "time": float(t),
                            "kind": "collision",
                            "entities": [oid1, oid2],
                            "value": None,
                            "src": []
                        })

        # Check exits - use velocity to predict if object will leave
        for oid in frame_oids:
            s = frame_data[oid]
            spd = s["speed"]

            # Exit if position is beyond boundary AND moving outward
            pos_magnitude = max(abs(s["x"]), abs(s["y"]))
            if pos_magnitude > exit_bound and spd > stationary_threshold:
                # Check if we already recorded this exit
                if not any(o["kind"] == "exit" and o["entities"][0] == oid for o in outcomes):
                    outcomes.append({
                        "time": float(t),
                        "kind": "exit",
                        "entities": [oid],
                        "value": None,
                        "src": []
                    })

    return [o for o in outcomes if o["time"] > start]

