    entry_times = {}
    for inp in inputs:
        if inp["kind"] == "enter":
            for eid in inp["entities"]:
                entry_times[eid] = inp["time"]

    active_objects = set(entry_times.keys())

    if not active_objects:
        return []

    # Get motion log table using children()
    child_nodes = children(doc, scope_node)
    motion_node = None
    for node in child_nodes:
        if node["kind"] == "table" and ": Motion log" in node["title"]:
            motion_node = node
            break

    # Build motion_data: obj_id -> list of (frame, x, y)
    motion_data = {}
    if motion_node:
        for row_idx, row_data in table_rows(motion_node):
            frame = int(row_data["frame"])
            obj_str = row_data["object"]
            obj_id = obj_str.split()[0]
            if obj_id not in active_objects:
                continue
            if obj_id not in motion_data:
                motion_data[obj_id] = []
            motion_data[obj_id].append((frame, float(row_data["x"]), float(row_data["y"])))

    # Sort by frame
    for oid in motion_data:
        motion_data[oid].sort(key=lambda t: t[0])

    if start is None:
        start = 0.0
    if horizon is None:
        horizon = recorded_end(doc, scope)

    if horizon is None or horizon <= start:
        return []

    start_frame = int(start)
    horizon_frame = int(horizon)

