    COLLISION_DIST = 0.47

    def get_pos(obj_id, frame):
        if obj_id not in motion_data or not motion_data[obj_id]:
            return None

        samples = motion_data[obj_id]
        # Exact match
        for f, x, y in samples:
            if f == frame:
                return (x, y)

        # Find bracketing frames
        lower = None
        upper = None
        for f, x, y in samples:
            if f <= frame:
                lower = (f, x, y)
            elif f > frame and upper is None:
                upper = (f, x, y)

        if lower and upper:
            t = (frame - lower[0]) / (upper[0] - lower[0])
            x = lower[1] + t * (upper[1] - lower[1])
            y = lower[2] + t * (upper[2] - lower[2])
            return (x, y)
        elif lower:
            return (lower[1], lower[2])
        elif upper:
