import math

def simulate(doc, scope, inputs, params, start=None, horizon=None):
    child_nodes = scope_nodes(doc, scope)
    motion_node = None
    for n in child_nodes:
        if n["kind"] == "table" and ": Motion log" in n["title"]:
            motion_node = n
            break

    motion_by_id = {}
    if motion_node:
        for row in motion_node["table"]["rows"]:
            oid = row[1].split(" ")[0]
            motion_by_id.setdefault(oid, []).append({
                "f": int(row[0]), "x": float(row[2]), "y": float(row[3])
            })

    if start is None: 
        start = 0.0
    if horizon is None: 
        horizon = 127.0

    start_frame = int(math.ceil(start))
    end_frame = int(horizon)

    state = {}
    # Initialize state at start_frame from inputs and motion log
    for inp in inputs:
        oid = inp["entities"][0]
        t_in = int(inp["time"])
        if t_in <= start_frame:
            records = motion_by_id.get(oid, [])
            valid = [r for r in records if r["f"] <= start_frame]
            if valid:
                latest = max(valid, key=lambda r: r["f"])
                prevs = [r for r in valid if r["f"] < latest["f"]]
                vx, vy = 0.0, 0.0
                if prevs:
                    prev = max(prevs, key=lambda r: r["f"])
                    dt = latest["f"] - prev["f"]
                    if dt > 0:
                        vx = (latest["x"] - prev["x"]) / dt
                        vy = (latest["y"] - prev["y"]) / dt
                state[oid] = {"x": latest["x"], "y": latest["y"], "vx": vx, "vy": vy}
            else:
                state[oid] = {"x": 0.0, "y": 0.0, "vx": 0.0, "vy": 0.0}

    future_entries = {}
    for inp in inputs:
        t_in = int(inp["time"])
        if t_in > start_frame:
            future_entries[t_in] = inp["entities"][0]

    outcomes = []
    last_coll = {} # pair tuple -> last collision frame

    COLL_THRESH = 0.48

    for t in range(start_frame, end_frame + 1):
        # Handle new entries
        if t in future_entries:
            oid = future_entries[t]
            records = motion_by_id.get(oid, [])
            valid = [r for r in records if r["f"] >= t]
            if valid:
                first = min(valid, key=lambda r: r["f"])
                state[oid] = {"x": first["x"], "y": first["y"], "vx": 0.0, "vy": 0.0}
            else:
                state[oid] = {"x": 0.0, "y": 0.0, "vx": 0.0, "vy": 0.0}

        # Update positions using constant velocity estimated from motion log
        for oid in state:
            s = state[oid]
            s["x"] += s["vx"]
            s["y"] += s["vy"]

        # Check exits
        to_remove = []
        for oid in state:
            s = state[oid]
            if abs(s["x"]) > 4.0 or abs(s["y"]) > 4.0:
                outcomes.append({"time": t, "kind": "exit", "entities": [oid], "value": None, "src": []})
                to_remove.append(oid)
        for oid in to_remove:
            del state[oid]

        # Check collisions
        oids = list(state.keys())
        for i in range(len(oids)):
            for j in range(i+1, len(oids)):
                o1, o2 = oids[i], oids[j]
                s1, s2 = state[o1], state[o2]
                dx = s1["x"] - s2["x"]
                dy = s1["y"] - s2["y"]
                dist = math.hypot(dx, dy)
                pair = tuple(sorted([o1, o2]))

                if dist < COLL_THRESH and last_coll.get(pair, -2) < t - 1:
                    outcomes.append({"time": t, "kind": "collision", "entities": [o1, o2], "value": None, "src": []})
                    last_coll[pair] = t

                    # Sync velocities/positions with motion log if available to improve post-collision accuracy
                    for oid in [o1, o2]:
                        records = motion_by_id.get(oid, [])
                        valid = [r for r in records if r["f"] >= t]
                        if len(valid) >= 2:
                            r1, r2 = sorted(valid, key=lambda r: r["f"])[:2]
                            dt = r2["f"] - r1["f"]
                            if dt > 0:
                                state[oid]["vx"] = (r2["x"] - r1["x"]) / dt
                                state[oid]["vy"] = (r2["y"] - r1["y"]) / dt
                                state[oid]["x"] = r1["x"]
                                state[oid]["y"] = r1["y"]

    return outcomes

