import math
import re

def simulate(doc, scope, inputs, params, start=None, horizon=None):
    child_nodes = scope_nodes(doc, scope)

    # Parse motion log
    motion_by_id = {}
    for n in child_nodes:
        if n["kind"] == "table" and ": Motion log" in n["title"]:
            for row in n["table"]["rows"]:
                if row[0] == "": continue
                oid = row[1].split(" ")[0]
                motion_by_id.setdefault(oid, []).append({
                    "f": int(row[0]), "x": float(row[2]), "y": float(row[3]),
                    "vx": float(row[4]), "vy": float(row[5])
                })

    if start is None: start = 0.0
    if horizon is None: horizon = 127.0

    start_f = int(math.ceil(start))
    end_f = int(horizon)
    thresh = params.get("stationary_threshold", 0.1)

    # Parse object materials
    obj_materials = {}
    for n in child_nodes:
        if n["kind"] == "list" and ": Objects" in n["title"]:
            for line in n.get("lines", []):
                m = re.match(r'Object (\d+): .*?material=(\w+)', line)
                if m:
                    obj_materials[m.group(1)] = m.group(2)

    # Build initial states from inputs + motion log
    states = {}
    for inp in inputs:
        oid = inp["entities"][0]
        t_init = max(int(inp["time"]), start_f)
        mat = obj_materials.get(oid, "metal")
        # Estimated friction per frame from CLEVRER physics
        mu = 0.015 if mat == "rubber" else 0.008

        records = motion_by_id.get(oid, [])
        valid = [r for r in records if r["f"] <= t_init]
        if valid:
            rec = max(valid, key=lambda r: r["f"])
            vx, vy = rec["vx"], rec["vy"]
            states[oid] = {"entry": t_init, "p0": (rec["x"], rec["y"]), "v0": (vx, vy), "mu": mu}
        else:
            states[oid] = {"entry": t_init, "p0": (0.0, 0.0), "v0": (0.0, 0.0), "mu": mu}

    def get_pos(st, t):
        if t < st["entry"]:
            return None
        t_rel = t - st["entry"]
        p0 = st["p0"]
        v0 = st["v0"]
        mu = st["mu"]
        s0 = math.hypot(v0[0], v0[1])

        # If below stationary threshold, treat as stopped
        if s0 < thresh:
            return p0

        t_stop = s0 / mu
        t_eff = min(t_rel, t_stop)
        if t_eff <= 0:
            return p0

        # Displacement along constant direction with linear deceleration
        factor = (s0 * t_eff - 0.5 * mu * t_eff * t_eff) / s0
        return (p0[0] + v0[0] * factor, p0[1] + v0[1] * factor)

    outcomes = []
    last_coll = {}  # pair -> last collision frame

    for t in range(start_f, end_f + 1):
        # Compute positions for all active objects
        pos = {}
        for oid, st in states.items():
            p = get_pos(st, t)
            if p is not None:
                pos[oid] = p

        # Check exits (scene bounds typically ~[-3.5, 3.5])
        for oid in list(pos.keys()):
            if abs(pos[oid][0]) > 3.5 or abs(pos[oid][1]) > 3.5:
                outcomes.append({"time": t, "kind": "exit", "entities": [oid], "value": None, "src": []})
                del pos[oid]

        # Check collisions
        oids = list(pos.keys())
        for i in range(len(oids)):
            for j in range(i+1, len(oids)):
                o1, o2 = oids[i], oids[j]
                p1, p2 = pos[o1], pos[o2]
                dx, dy = p1[0]-p2[0], p1[1]-p2[1]
                dist = math.hypot(dx, dy)
                pair = tuple(sorted([o1, o2]))

                # Collision threshold ~0.5 for CLEVRER object sizes
                if dist < 0.52 and last_coll.get(pair, -5) < t - 1:
                    outcomes.append({"time": t, "kind": "collision", "entities": [o1, o2], "value": None, "src": []})
                    last_coll[pair] = t

    return outcomes

