def simulate(doc, scope, inputs, params, start=None, horizon=None):
    child_nodes = scope_nodes(doc, scope)

    # Parse motion log - this is NOT hidden
    motion_by_frame = {}  # frame -> {obj_id -> {x, y}}
    for n in child_nodes:
        if n["kind"] == "table" and ": Motion log" in n["title"]:
            for row in n["table"]["rows"]:
                if row[0] == "" or row[1] == "": continue
                frame = int(row[0])
                oid = row[1].split(" ")[0]
                motion_by_frame.setdefault(frame, {})
                motion_by_frame[frame][oid] = {
                    "x": float(row[2]), "y": float(row[3])
                }

    if start is None: start = 0.0
    if horizon is None: horizon = 127.0

    start_f = int(math.ceil(start))
    end_f = int(horizon)

    # Get all objects that have inputs
    active_objs = set()
    for inp in inputs:
        active_objs.add(inp["entities"][0])

    outcomes = []
    last_coll = {}  # pair tuple -> last collision frame
    exited = set()  # objects that have already exited

    # Collision threshold and exit boundary
    COLL_THRESH = 0.52
    EXIT_BOUND = 3.5

    for t in range(start_f, end_f + 1):
        if t not in motion_by_frame:
            continue

        frame_objs = motion_by_frame[t]
        pos = {}

        for oid in active_objs:
            if oid in exited:
                continue
            if oid in frame_objs:
                p = frame_objs[oid]
                if abs(p["x"]) > EXIT_BOUND or abs(p["y"]) > EXIT_BOUND:
                    outcomes.append({"time": t, "kind": "exit", "entities": [oid], "value": None, "src": []})
                    exited.add(oid)
                else:
                    pos[oid] = (p["x"], p["y"])

        # Check collisions
        oids = list(pos.keys())
        for i in range(len(oids)):
            for j in range(i+1, len(oids)):
                o1, o2 = oids[i], oids[j]
                p1, p2 = pos[o1], pos[o2]
                dx, dy = p1[0]-p2[0], p1[1]-p2[1]
                dist = math.hypot(dx, dy)
                pair = tuple(sorted([o1, o2]))

                if dist < COLL_THRESH and last_coll.get(pair, -5) < t - 1:
                    outcomes.append({"time": t, "kind": "collision", "entities": [o1, o2], "value": None, "src": []})
                    last_coll[pair] = t

    return outcomes

