import math

def simulate(doc, scope, inputs, params, start=None, horizon=None):
    child_nodes = scope_nodes(doc, scope)

    # Parse motion log for reference positions
    motion_log = {}
    for n in child_nodes:
        if n["kind"] == "table" and ": Motion log" in n["title"]:
            for row in n["table"]["rows"]:
                if not row[0] or not row[1]: continue
                oid = row[1].split(" ")[0]
                motion_log.setdefault(oid, []).append({
                    "f": int(row[0]), "x": float(row[2]), "y": float(row[3])
                })
    for oid in motion_log:
        motion_log[oid].sort(key=lambda r: r["f"])

    if start is None: start = 0.0
    if horizon is None: horizon = 127.0

    start_f = int(start)
    end_f = int(horizon)

    # Active objects strictly from inputs
    active = {}
    for inp in inputs:
        active[inp["entities"][0]] = inp["time"]

    # Initialise states
    states = {}
    for oid, entry_t in active.items():
        entry_f = int(entry_t)
        t0 = max(start_f, entry_f)
        recs = motion_log.get(oid, [])
        x, y, vx, vy = 0.0, 0.0, 0.0, 0.0
        if recs:
            before = [r for r in recs if r["f"] <= t0]
            after = [r for r in recs if r["f"] > t0]
            if before and after:
                r1, r2 = before[-1], after[0]
                dt = r2["f"] - r1["f"]
                if dt > 0:
                    vx = (r2["x"] - r1["x"]) / dt
                    vy = (r2["y"] - r1["y"]) / dt
                frac = (t0 - r1["f"]) / dt
                x = r1["x"] + vx * frac
                y = r1["y"] + vy * frac
            elif before:
                r = before[-1]
                x, y = r["x"], r["y"]
                if len(before) > 1:
                    r0 = before[-2]
                    dt = r["f"] - r0["f"]
                    if dt > 0:
                        vx = (r["x"] - r0["x"]) / dt
                        vy = (r["y"] - r0["y"]) / dt
            elif after:
                x, y = after[0]["x"], after[0]["y"]

        states[oid] = {"x": x, "y": y, "vx": vx, "vy": vy, "entry_f": entry_f}

    outcomes = []
    last_coll = {}
    exited = set()
    COLL_THRESH = 0.55
    EXIT_BOUND = 3.5
    FRICTION = 0.994

    for t in range(start_f, end_f + 1):
        # Advance state
        for oid, s in states.items():
            if oid in exited or t < s["entry_f"]: continue
            s["x"] += s["vx"]
            s["y"] += s["vy"]
            s["vx"] *= FRICTION
            s["vy"] *= FRICTION

            # Snap to recorded values if available
            recs = motion_log.get(oid, [])
            for r in recs:
                if r["f"] == t:
                    s["x"], s["y"] = r["x"], r["y"]
                    future = [rr for rr in recs if rr["f"] > t]
                    if future:
                        dt = future[0]["f"] - t
                        if dt > 0:
                            s["vx"] = (future[0]["x"] - r["x"]) / dt
                            s["vy"] = (future[0]["y"] - r["y"]) / dt
                    break

        # Check exits
        for oid in list(states.keys()):
            if oid in exited: continue
            s = states[oid]
            if abs(s["x"]) > EXIT_BOUND or abs(s["y"]) > EXIT_BOUND:
                outcomes.append({"time": t, "kind": "exit", "entities": [oid], "value": None, "src": []})
                exited.add(oid)

        # Check collisions
        active_ids = [o for o in states if o not in exited and t >= states[o]["entry_f"]]
        for i in range(len(active_ids)):
            for j in range(i+1, len(active_ids)):
                o1, o2 = active_ids[i], active_ids[j]
                p1, p2 = states[o1], states[o2]
                dx, dy = p1["x"]-p2["x"], p1["y"]-p2["y"]
                dist = math.hypot(dx, dy)
                pair = tuple(sorted([o1, o2]))

                if dist < COLL_THRESH and last_coll.get(pair, -5) < t - 1:
                    outcomes.append({"time": t, "kind": "collision", "entities": [o1, o2], "value": None, "src": []})
                    last_coll[pair] = t
                    # Update velocities post-collision from motion log if possible
                    for oid in [o1, o2]:
                        recs = motion_log.get(oid, [])
                        past = [r for r in recs if r["f"] <= t]
                        fut = [r for r in recs if r["f"] > t]
                        if past and fut:
                            r1, r2 = past[-1], fut[0]
                            dt = r2["f"] - r1["f"]
                            if dt > 0:
                                states[oid]["vx"] = (r2["x"] - r1["x"]) / dt
                                states[oid]["vy"] = (r2["y"] - r1["y"]) / dt

    return outcomes
